(() => {
 const originals=[];
 const probe=window.__storageProbe={active:null};
 function memory(label){const s=probe.active;if(s&&s.mode==='memory')s.heap.push({at_ms:performance.now()-s.started,label,used_js_heap_bytes:performance.memory.usedJSHeapSize,total_js_heap_bytes:performance.memory.totalJSHeapSize});}
 function traceRequest(receiver,method,request,args){const s=probe.active;if(!s)return;const started=performance.now();const store=receiver.objectStore?receiver.objectStore.name:receiver.name;const index=receiver.objectStore?receiver.name:null;request.addEventListener('success',()=>{memory('idb:'+store+':'+method);const v=request.result;const rows=Array.isArray(v)?v:(v===undefined?[]:[v]);let payloadBytes=0,blobBytes=0;if(s.mode==='trace'){const e=new TextEncoder();for(const row of rows){if(row&&row.payload)payloadBytes+=e.encode(JSON.stringify(row.payload)).byteLength;if(row&&row.blob)blobBytes+=row.blob.size;}}s.reads.push({store,index,method,records:rows.length,payload_bytes:s.mode==='trace'?payloadBytes:null,blob_reference_bytes:blobBytes,request_ms:performance.now()-started});},{once:true});request.addEventListener('error',()=>s.errors.push({store,method,error:request.error&&request.error.name}),{once:true});}
 for(const proto of [IDBObjectStore.prototype,IDBIndex.prototype])for(const method of ['get','getAll']){const original=proto[method];originals.push([proto,method,original]);proto[method]=function(...args){const r=original.apply(this,args);traceRequest(this,method,r,args);return r;};}
 const originalArrayBuffer=Blob.prototype.arrayBuffer;originals.push([Blob.prototype,'arrayBuffer',originalArrayBuffer]);Blob.prototype.arrayBuffer=function(...args){const size=this.size;return originalArrayBuffer.apply(this,args).then(b=>{const s=probe.active;if(s){s.blob_reads.push({bytes:size});memory('blob:arrayBuffer');}return b;});};
 probe.begin=(mode)=>{probe.active={mode,started:performance.now(),reads:[],blob_reads:[],heap:[],errors:[]};memory('start');if(mode==='memory')probe.active.timer=setInterval(()=>memory('interval'),5);};
 probe.end=()=>{memory('finish');const s=probe.active;if(s.timer)clearInterval(s.timer);s.elapsed_ms=performance.now()-s.started;delete s.timer;probe.active=null;return s;};
 probe.restore=()=>{for(const [p,m,f]of originals)p[m]=f;};
})();

measurement_source:
async function (operation, mode, round) {
  return await storageTab.run(async ({ page }, opt) => {
    const cdp = await page.target().createCDPSession();
    const main = async (fn, ...args) => {
      const r = await cdp.send("Runtime.evaluate", { expression: "(" + fn.toString() + ")(" + args.map((a) => JSON.stringify(a)).join(",") + ")", awaitPromise: true, returnByValue: true });
      if (r.exceptionDetails)
        throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
      return r.result.value;
    };
    const projectSelector = '#project-list .project-row[data-project-id="' + opt.projectId + '"] button[data-action="open"]';
    if (opt.operation === "open") {
      if (await page.$eval("#project-view", (e) => !e.hidden)) {
        await page.click("#back-home");
        await page.waitForSelector(projectSelector);
      }
    } else if (opt.operation === "save") {
      if (await page.$eval("#project-view", (e) => e.hidden)) {
        await page.click(projectSelector);
        await page.waitForFunction(() => !document.querySelector("#project-view").hidden);
      }
      await page.click('[data-stage-nav="intake"]');
    }
    let expectedVersion = null;
    if (opt.operation === "save") {
      expectedVersion = await main(async (pid) => {
        const m = await (typeof __omp_import__ === "function" ? __omp_import__ : (s, o) => import(s, o))("/storage/index.js");
        const o = await m.openStorage();
        const d = await o.repository.documents.getLatest(pid, "product_input", "intake");
        o.close();
        return d.version + 1;
      }, opt.projectId);
      await page.$eval("#intake-focus", (e, v) => {
        e.value = v;
        e.dispatchEvent(new Event("input", { bubbles: true }));
      }, "accepted-" + opt.round + "-" + opt.mode);
    }
    await main(() => { delete window.__lastMeasurementExport; }); await cdp.send("HeapProfiler.collectGarbage");
    const initialHeap = await cdp.send("Runtime.getHeapUsage");
    const heapSamples = [{ at_ms: 0, ...initialHeap }];
    let sampling = true;
    const samplerStart = Date.now();
    const sampleLoop = opt.mode === "memory" ? (async () => {
      while (sampling) {
        heapSamples.push({ at_ms: Date.now() - samplerStart, ...await cdp.send("Runtime.getHeapUsage") });
        await new Promise((r) => setTimeout(r, 5));
      }
    })() : Promise.resolve();
    await main((mode) => {
      window.__storageProbe.active = null;
      if (mode !== "latency")
        window.__storageProbe.begin(mode);
    }, opt.mode);
    let result = null;
    let elapsed = null;
    if (opt.operation === "export") {
      result = await main(async (pid) => {
        const m = await (typeof __omp_import__ === "function" ? __omp_import__ : (s, o) => import(s, o))("/storage/index.js");
        const o = await m.openStorage();
        const started = performance.now();
        try {
          const out = await m.exportProjectPackage(o.repository, pid);
          const elapsed = performance.now() - started;
          window.__lastMeasurementExport = out;
          return { elapsed_ms: elapsed, zip_bytes: out.bytes.length, manifest: out.manifest };
        } finally {
          o.close();
        }
      }, opt.projectId);
      elapsed = result.elapsed_ms;
    } else {
      const selector = opt.operation === "open" ? projectSelector : "#intake-save";
      await main((selector) => {
        document.querySelector(selector).addEventListener("click", () => {
          window.__measurementOperationStarted = performance.now();
        }, { capture: true, once: true });
      }, selector);
      await page.click(selector);
      if (opt.operation === "open")
        await page.waitForFunction(() => !document.querySelector("#project-view").hidden && document.querySelector("#project-view").dataset.ready === "1");
      else
        await page.waitForFunction((v) => document.querySelector("#intake-draft").textContent.includes("版本 " + v), {}, expectedVersion);
      elapsed = await main(() => performance.now() - window.__measurementOperationStarted);
    }
    const trace = await main((mode) => mode === "latency" ? null : window.__storageProbe.end(), opt.mode);
    sampling = false;
    await sampleLoop;
    heapSamples.push({ at_ms: Date.now() - samplerStart, ...await cdp.send("Runtime.getHeapUsage") });
    await cdp.detach();
    return { operation: opt.operation, mode: opt.mode, round: opt.round, project_id: opt.projectId, elapsed_ms: elapsed, expected_version: expectedVersion, trace, cdp_heap_samples: heapSamples, export_result: result };
  }, { args: [{ operation, mode, round, projectId: storageTargetId }] });
}

long_plan_save_source:
async function (mode) {
  return await storageTab.run(async ({ page }, opt) => {
    const c = await page.target().createCDPSession();
    const run = async (fn, ...args) => {
      const r = await c.send("Runtime.evaluate", { expression: "(" + fn.toString() + ")(" + args.map((x) => JSON.stringify(x)).join(",") + ")", awaitPromise: true, returnByValue: true });
      if (r.exceptionDetails)
        throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
      return r.result.value;
    };
    await run(async (pid) => {
      const m = await (typeof __omp_import__ === "function" ? __omp_import__ : (s, o) => import(s, o))("/storage/index.js");
      window.__planMeasureOpen = await m.openStorage();
      window.__planMeasureOld = await window.__planMeasureOpen.repository.documents.getLatest(pid, "suite_plan", "suite");
    }, opt.pid);
    await c.send("HeapProfiler.collectGarbage");
    const samples = [{ at_ms: 0, ...await c.send("Runtime.getHeapUsage") }];
    let running = true;
    const started = Date.now();
    const sampling = opt.mode === "memory" ? (async () => {
      while (running) {
        samples.push({ at_ms: Date.now() - started, ...await c.send("Runtime.getHeapUsage") });
        await new Promise((r) => setTimeout(r, 5));
      }
    })() : Promise.resolve();
    const result = await run(async (pid, mode) => {
      window.__storageProbe.active = null;
      if (mode !== "latency")
        window.__storageProbe.begin(mode);
      const started = performance.now();
      const row = await window.__planMeasureOpen.repository.documents.save(pid, { kind: "suite_plan", documentId: "suite", payload: window.__planMeasureOld.payload, expectedVersion: window.__planMeasureOld.version });
      const elapsed = performance.now() - started;
      const trace = mode === "latency" ? null : window.__storageProbe.end();
      window.__planMeasureOpen.close();
      return { operation: "save_2000_version_plan", mode, old_version: window.__planMeasureOld.version, new_version: row.version, elapsed_ms: elapsed, trace };
    }, opt.pid, opt.mode);
    running = false;
    await sampling;
    samples.push({ at_ms: Date.now() - started, ...await c.send("Runtime.getHeapUsage") });
    await c.detach();
    return { ...result, cdp_heap_samples: samples };
  }, { args: [{ pid: storageTargetId, mode }], timeout: 90 });
}
